    @inline(__always)
    private func checkShuffledPer4LanesUncheckedConstantImmediates(
        _ i3: Int,
        _ i2: Int,
        _ i1: Int,
        _ i0: Int
    ) {
        let mismatches = Mismatches(
            "shuffledPer4Lanes unchecked with i3 \(i3), i2 \(i2), i1 \(i1), i0 \(i0)"
        )
        let aInputs = Inputs.vectors(H.Vector.self, seed: 0xD564_09C4_3AFB_8139)
        for a in aInputs {
            mismatches.check(
                unsafe H.shuffledPer4Lanes(a, unchecked: i3, i2, i1, i0),
                H.Vector(
                    raw: HighwayReference.shuffledPer4LanesU8(
                        a.raw,
                        Int32(truncatingIfNeeded: i3),
                        Int32(truncatingIfNeeded: i2),
                        Int32(truncatingIfNeeded: i1),
                        Int32(truncatingIfNeeded: i0)
                    )
                ),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

